\textrm{Row 2}: & \qquad & & & 1 & & 2 & & 1 & & & &\\ \vspace{0.1in}
\textrm{Row 3}: & \qquad & & 1 && 3 && 3 && 1&& \\ \vspace{0.1in}
\textrm{Row 4}: & \qquad & 1&& 4 && 6 && 4 && 1
