label("$25$",(2.5,4.5));

label("$40$",(3.5,0.5));
label("$39$",(3.5,1.5));
label("$38$",(3.5,2.5));
label("$37$",(3.5,3.5));
label("$36$",(3.5,4.5));

label("$41$",(4.5,0.5));
label("$42$",(4.5,1.5));
label("$43$",(4.5,2.5));
label("$44$",(4.5,3.5));
